{
  "resourceType": "Bundle",
  "type": "collection",
  "entry": [
    {
      "fullUrl": "https://example.org/fhir/Patient/patient-1",
      "resource": {
        "resourceType": "Patient",
        "id": "patient-1",
        "gender": "male"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-1",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-1",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Gambling disorder, moderate to severe"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Personality disorder, likely cluster B / borderline personality traits"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Gambling pattern, control, and associated harms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports electronic gaming machine gambling most days at his workplace and sometimes at a nearby club, with some late-night online sports betting. Ongoing for at least 12 months and worse since the venue reopened after COVID. Preoccupied with gambling, including thinking about which machine is due at dinner. Reports difficulty controlling gambling: plans to spend $50 or be home by 9 pm but stays for hours and spends a few hundred dollars; last week spent about $1,200 over three nights. Reports being behind on credit card and Afterpay payments and having a small personal loan; thinks one good night will fix it. Reports increased conflict with his ex-partner about child support and conflict with his mother about money. Has stopped gym and fishing activities, preferring to keep money for gambling."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Brief problem gambling screen"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Both questions positive; screen indicates probable gambling disorder. PGSI not completed because of time and tangential history."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Mood"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Describes mood as flat and stressed in relation to gambling losses and debt, and as stressed and a bit ashamed during the assessment. No persistent low mood or anhedonia outside the gambling context."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Anxiety and panic symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Anxiety is mostly related to money worries. No panic reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Sleep"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Poor sleep, with late-night phone use and betting until 2–3 am; reports insomnia after gambling losses."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Suicidal thoughts and safety"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No current suicidal ideation or plan. Occasionally thinks it would be easier to disappear, but denies intent. Protective factors identified: daughter and close relationship with mother. Clinician assessed no acute suicide risk today and noted high psychosocial and financial risk if gambling continues."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Alcohol use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports 3–4 beers after late shifts and 6–7 beers on pay nights. Denies morning drinking and blackouts."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Other drug use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports no other drug use."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Psychiatric history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports past psychiatric contact in his 20s after a major workplace conflict in which he smashed a glass. Was told he had a personality disorder, 'kind of borderline'; describes impulsivity and reacting strongly when people upset him. Participated in DBT groups and stopped. No current psychiatrist, no current medications, and no past psychiatric admissions reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "General appearance and behavior"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Well and in no distress. Tangential historian requiring frequent redirection; cooperative and mildly fidgety."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Speech"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Speech increases when discussing gambling."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Affect"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Affect congruent with mood."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Psychosis"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No psychosis observed."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Insight and judgment"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Insight fair regarding gambling; judgment impaired around chasing losses."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Blood pressure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "component": [
          {
            "code": {
              "text": "Systolic blood pressure"
            },
            "valueQuantity": {
              "value": 124,
              "unit": "mmHg"
            }
          },
          {
            "code": {
              "text": "Diastolic blood pressure"
            },
            "valueQuantity": {
              "value": 78,
              "unit": "mmHg"
            }
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "Heart rate"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 82,
          "unit": "beats/min"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-17",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-17",
        "status": "final",
        "code": {
          "text": "Respiratory rate"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 14,
          "unit": "breaths/min"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-18",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-18",
        "status": "final",
        "code": {
          "text": "Oxygen saturation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 99,
          "unit": "%"
        },
        "note": [
          {
            "text": "On room air."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-19",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-19",
        "status": "final",
        "code": {
          "text": "Temperature"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Afebrile."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-20",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-20",
        "status": "final",
        "code": {
          "text": "Body mass index"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 26,
          "unit": "kg/m2"
        },
        "note": [
          {
            "text": "Approximate."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-21",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-21",
        "status": "final",
        "code": {
          "text": "Mood and anxiety disorder risk assessment"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Clinician assessed the patient as at risk of mood or anxiety disorder, and of possible future alcohol misuse if the pattern continues; no such diagnosis was established in this note."
      }
    }
  ]
}
